import * as React from "react";

export type NavCompassCircleIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function NavCompassCircleIcon({ size = 20, ...props }: NavCompassCircleIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <circle cx="12" cy="12" r="8.5" /><path d="M15 9l-2 5-4 1 2-5" />
    </svg>
  );
}
